import{_ as t,o as e,c as r,a0 as d}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"三维装箱 BPP3D","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp3d/index.md","filePath":"zh-cn/frameworks/bpp3d/index.md"}'),o={name:"zh-cn/frameworks/bpp3d/index.md"};function i(l,a,n,h,c,s){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="三维装箱-bpp3d" tabindex="-1">三维装箱 BPP3D <a class="header-anchor" href="#三维装箱-bpp3d" aria-label="Permalink to &quot;三维装箱 BPP3D&quot;">​</a></h1><p>货物具有长宽高和重量，需要选择箱型、朝向和放置位置，最后得到可检查、可展示的装载方案。第一课只处理长方体，不从圆柱与复杂支撑开始。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>货物与包装</td><td><code>Item</code> / <code>Package</code></td><td>尺寸、重量、物料和允许朝向</td></tr><tr><td>箱型</td><td><code>BinType</code></td><td>几何、承重和类型身份</td></tr><tr><td>箱层候选</td><td><code>BinLayer</code></td><td>箱型、需求覆盖与放置追踪</td></tr><tr><td>应用服务</td><td><code>ColumnGenerationApplicationService</code></td><td>主问题、生成、最终选择与装载分析</td></tr><tr><td>终态验证</td><td><code>PackingGeometryGuard</code></td><td>越界、重叠和对应形状路径的合法性</td></tr></tbody></table><p>候选列描述可选的装载结构，不是已经完成的最终装箱。优化选择、实际放置和报告都要接通。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>Kotlin 的应用请求、标准执行器和 packing analyzer 组成入口。Rust 提供 materialized / CSV 路径，以 RMP 与 final executor 注入后端。不能只把 Kotlin 类型改成蛇形命名就当作 Rust 实现。</p><p>先用固定箱型和少量 seed 验证装配，再引入自动候选、多箱型与目标配置。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>圆柱支持依赖轴向以及生成、支撑、终态验证路径，不代表任意三维旋转都支持。</li><li>装载率应使用对应形状的真实体积，不能把外接体积当实占体积。</li><li>外部 renderer 的实现不在框架内；输出 DTO 不等于已经启动可视化页面。</li><li><code>finalSolved</code>、packing snapshot 和定价诊断应一起检查，不能只看非空候选列表。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-loading.html">第一次三维装箱</a>，学习从候选选择到最终放置。</li><li>增加箱型、重量和费用，明确目标权重的业务含义。</li><li>综合航空装载可参考<a href="/ospf/zh-cn/examples/framework-example2.html">复杂示例 2</a>，但行业安全规则不因使用 BPP3D 而自动具备。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/README_ch.md" target="_blank" rel="noreferrer">Kotlin 入口与形状路径矩阵</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/README_ch.md" target="_blank" rel="noreferrer">Rust 入口与领域契约</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">多箱型与目标配置</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const m=t(o,[["render",i]]);export{f as __pageData,m as default};
